def write_csv(path,rows):
    with Path(path).open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
def readable(text):
    # Correct spacing in generated quantitative prose; preserve URLs, paths
    # and formal names rather than applying a global identifier rewrite.
    for old,new in [('included633','included 633'),('including605','including 605'),('and27,','and 27,'),('used9,','used 9,'),('across33','across 33'),('of33','of 33'),('has165','has 165'),('supplied165','supplied 165'),('and165','and 165'),('was90','was 90'),('nominal90','nominal 90'),('et al.(2023;https','et al. (2023; https'),('4,820verifiedphysicalDNApairs','4,820 verified physical DNA pairs'),('9,602original','9,602 original'),('9,602source','9,602 source'),('source-matched','source-matched'),('HEK293cells','HEK293 cells'),('HEK293Tcultures','HEK293T cultures'),('log2effect','log2 effect'),('log2reporter','log2 reporter'),('log2units','log2 units'),('nominal90','nominal 90'),('90%interval','90% interval'),('source90','source 90'),('33markers','33 markers'),('165predictions','165 predictions'),('4,820verifiedDNApairs','4,820 verified DNA pairs'),('ForHNP','For HNP'),('ForHEK293','For HEK293'),('sequence_only:','Sequence inputs only:'),('AVI_added:','AVI added as an input:'),('after these results','after these results')]:text=text.replace(old,new)
    text=re.sub(r'(?<=\d)(?=(?:measurements|actual|separate|development|absolute|auxiliary|original|source|verified|project|for|log2|logarithmic)\b)',' ',text)
    text=re.sub(r'(?<=%)(?=(?:of|relative|interval|improvement)\b)',' ',text)
    text=re.sub(r'\b(included|was|were|had|error|compared with|with|covered|and|for|correlation was|ranking correlation|ranking|baseline|across|representing)(?=\d)',r'\1 ',text)
    text=text.replace(':'+'retain',': retain').replace(':do not retain',': do not retain').replace('toexclude','to exclude').replace('toretain','to retain')
    text=re.sub(r'(?<=[a-z])(?=\d{2,})',' ',text)
    text=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',text)
    text=re.sub(r'\b(The|the|all|and|of|for|with|from)(?=\d)',r'\1 ',text)
    text=text.replace('HEK293 T','HEK293T').replace('test:9,602','test: 9,602').replace('bpgenomic','bp genomic').replace('bpinputs','bp inputs')
    return text
